// "New table" screen: a name, primary key chips, and an editable list of columns
// (column_name, data_type, is_nullable, column_default). Generates and runs CREATE TABLE.
(function () {
  const { h, icon, toast, modal, contextMenu } = window.U;

  const TYPES = [
    'NUMBER', 'NUMBER(10)', 'NUMBER(19)', 'NUMBER(12,2)', 'INTEGER', 'FLOAT', 'BINARY_DOUBLE',
    'NUMBER GENERATED BY DEFAULT AS IDENTITY', 'NUMBER GENERATED ALWAYS AS IDENTITY',
    'VARCHAR2(50)', 'VARCHAR2(100)', 'VARCHAR2(255)', 'VARCHAR2(4000)', 'NVARCHAR2(255)', 'CHAR(1)',
    'CLOB', 'NCLOB', 'BLOB', 'RAW(16)',
    'DATE', 'TIMESTAMP', 'TIMESTAMP WITH TIME ZONE', 'TIMESTAMP WITH LOCAL TIME ZONE',
    'BOOLEAN', 'JSON',
  ];
  const DEFAULTS = ['NULL', 'SYSDATE', 'SYSTIMESTAMP', 'CURRENT_TIMESTAMP', 'SYS_GUID()', '0', '1', "'Y'", "'N'"];

  let seq = 0;
  let listsAdded = false;
  function ensureLists() {
    if (listsAdded) return;
    listsAdded = true;
    document.body.append(
      h('datalist', { id: 'ct-types' }, TYPES.map((t) => h('option', { value: t }))),
      h('datalist', { id: 'ct-defaults' }, DEFAULTS.map((t) => h('option', { value: t }))));
  }

  /**
   * opts = { owner, onCreated(tableName), runCreate(spec) -> Promise<{table}>, previewSql(spec) -> Promise<string>,
   *          openInEditor(sql), confirmProd() -> Promise<bool> }
   * Returns a tab object for app.js (title, icon, el, onKey, onShow, isDirty).
   */
  function createTableTab(opts) {
    ensureLists();
    const rid = () => ++seq;
    const st = {
      name: `untitled_table_${Math.floor(10000 + Math.random() * 90000)}`,
      cols: [{ id: rid(), name: 'id', type: 'NUMBER GENERATED ALWAYS AS IDENTITY', nullable: true, def: '' }],
      pk: [], // column row ids
      busy: false,
    };

    const nameInput = h('input', { class: 'ct-name mono', spellcheck: 'false' });
    nameInput.value = st.name;
    nameInput.addEventListener('input', () => { st.name = nameInput.value; tab.title = st.name.trim() || 'New table'; tab.rename && tab.rename(); });

    const chipBox = h('div', { class: 'ct-chips' });
    const pkInput = h('input', { class: 'ct-pk-input mono', placeholder: 'Add column', list: 'ct-pkcols-' + seq, spellcheck: 'false' });
    const pkList = h('datalist', { id: 'ct-pkcols-' + seq });
    const pkField = h('div', { class: 'ct-pk', onclick: () => pkInput.focus() }, chipBox, pkInput, pkList);

    const tbody = h('tbody');
    const table = h('table', { class: 'ct-grid' },
      h('colgroup', null, h('col', { style: { width: '230px' } }), h('col', { style: { width: '300px' } }), h('col', { style: { width: '130px' } }), h('col', { style: { width: '220px' } }), h('col', { style: { width: '34px' } })),
      h('thead', null, h('tr', null, h('th', null, 'column_name'), h('th', null, 'data_type'), h('th', null, 'is_nullable'), h('th', null, 'column_default'), h('th', null, ''))),
      tbody);
    const gridWrap = h('div', { class: 'ct-wrap' }, table);
    const errBox = h('div', { class: 'ct-errors hidden' });

    const previewBtn = h('button', { class: 'btn sm', onclick: () => preview() }, icon('code'), 'Preview SQL');
    const addBtn = h('button', { class: 'btn sm ghost', onclick: () => { addCol(); } }, icon('plus'), 'Column');
    const createBtn = h('button', { class: 'btn sm primary', title: 'Create table (Ctrl+S)', onclick: () => create() }, 'Create table');
    const schemaLabel = h('span', { class: 'muted ct-schema' }, `in ${opts.owner}`);

    const head = h('div', { class: 'ct-head' },
      h('label', { class: 'ct-label' }, 'Name'), nameInput, schemaLabel,
      h('label', { class: 'ct-label ct-gap' }, 'Primary'), pkField);
    const footer = h('div', { class: 'pager ct-foot' }, addBtn, h('span', { class: 'muted ct-hint' }, 'Type in the empty row to add a column · right-click a row to move or delete it'), h('div', { class: 'spacer' }), previewBtn, createBtn);
    const el = h('div', { class: 'tabview ct' }, head, errBox, gridWrap, footer);

    // ---------- rendering ----------
    function spec() {
      const byId = new Map(st.cols.map((c) => [c.id, c]));
      return {
        owner: opts.owner,
        name: st.name,
        columns: st.cols.map((c) => ({ name: c.name, type: c.type, nullable: c.nullable, default: c.def })),
        primaryKey: st.pk.map((id) => byId.get(id)).filter(Boolean).map((c) => c.name),
      };
    }

    function paintPk() {
      chipBox.innerHTML = '';
      const byId = new Map(st.cols.map((c) => [c.id, c]));
      st.pk = st.pk.filter((id) => byId.has(id) && byId.get(id).name.trim());
      st.pk.forEach((id) => chipBox.append(h('span', { class: 'ct-chip mono' }, byId.get(id).name,
        h('button', { class: 'ct-chip-x', title: 'Remove', onclick: (e) => { e.stopPropagation(); st.pk = st.pk.filter((x) => x !== id); paintPk(); paintRows(); } }, icon('x')))));
      pkList.innerHTML = '';
      st.cols.filter((c) => c.name.trim() && !st.pk.includes(c.id)).forEach((c) => pkList.append(h('option', { value: c.name })));
      pkInput.placeholder = st.pk.length ? '' : 'Add column';
    }

    function addPk(name) {
      const c = st.cols.find((x) => x.name.trim().toUpperCase() === String(name).trim().toUpperCase());
      if (!c) { toast(`No column named ${name}`, 'err'); return; }
      if (!st.pk.includes(c.id)) st.pk.push(c.id);
      pkInput.value = '';
      paintPk();
      paintRows();
    }
    pkInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && pkInput.value.trim()) { e.preventDefault(); addPk(pkInput.value); }
      if (e.key === 'Backspace' && !pkInput.value && st.pk.length) { st.pk.pop(); paintPk(); paintRows(); }
    });
    pkInput.addEventListener('change', () => { if (st.cols.some((c) => c.name === pkInput.value)) addPk(pkInput.value); });

    function cellInput(c, key, attrs = {}) {
      const input = h('input', { class: 'ct-cell mono', spellcheck: 'false', autocomplete: 'off', ...attrs });
      input.value = c[key] || '';
      input.addEventListener('input', () => {
        c[key] = input.value;
        if (key === 'name') paintPk();
        markRow(input.closest('tr'), c);
      });
      return input;
    }

    const typedPk = (c) => /\bPRIMARY\s+KEY\b/i.test(c.type || '');
    function markRow(tr, c) {
      if (!tr) return;
      tr.classList.toggle('pk', st.pk.includes(c.id) || typedPk(c));
      tr.classList.toggle('incomplete', !!(c.name.trim() && !c.type.trim()) || !!(!c.name.trim() && c.type.trim()));
    }

    function paintRows(focus) {
      tbody.innerHTML = '';
      st.cols.forEach((c, i) => {
        const isPk = st.pk.includes(c.id) || typedPk(c);
        const nullSel = h('select', { class: 'ct-cell', disabled: isPk, title: isPk ? 'Primary key columns are always NOT NULL' : '' },
          h('option', { value: 'YES' }, 'YES'), h('option', { value: 'NO' }, 'NO'));
        nullSel.value = isPk || !c.nullable ? 'NO' : 'YES';
        nullSel.addEventListener('change', () => { c.nullable = nullSel.value === 'YES'; });
        const tr = h('tr', {
          class: 'ct-row' + (isPk ? ' pk' : ''),
          oncontextmenu: (e) => {
            e.preventDefault();
            contextMenu(e.clientX, e.clientY, [
              { label: isPk ? 'Remove from primary key' : 'Add to primary key', icon: 'key', disabled: !c.name.trim(), onClick: () => { if (isPk) st.pk = st.pk.filter((x) => x !== c.id); else st.pk.push(c.id); paintPk(); paintRows(); } },
              {
                label: /IDENTITY/i.test(c.type) ? 'Remove identity (auto-increment)' : 'Make identity (auto-increment)',
                onClick: () => {
                  if (/IDENTITY/i.test(c.type)) c.type = 'NUMBER';
                  else { c.type = 'NUMBER GENERATED ALWAYS AS IDENTITY'; c.def = ''; if (!st.pk.length && c.name.trim()) st.pk.push(c.id); }
                  paintRows(); paintPk();
                },
              },
              '-',
              { label: 'Insert column above', icon: 'plus', onClick: () => addCol(i) },
              { label: 'Move up', disabled: i === 0, onClick: () => move(i, -1) },
              { label: 'Move down', disabled: i === st.cols.length - 1, onClick: () => move(i, 1) },
              '-',
              { label: 'Delete column', icon: 'trash', danger: true, onClick: () => removeCol(i) },
            ]);
          },
        },
        h('td', null, isPk ? icon('key', 'ct-key') : null, cellInput(c, 'name', { placeholder: 'column_name' })),
        h('td', null, cellInput(c, 'type', { list: 'ct-types', placeholder: 'data type' })),
        h('td', null, nullSel),
        h('td', null, cellInput(c, 'def', { list: 'ct-defaults', placeholder: 'NULL' })),
        h('td', { class: 'ct-del' }, h('button', { class: 'icon-btn', title: 'Delete column', tabindex: '-1', onclick: () => removeCol(i) }, icon('x'))));
        markRow(tr, c);
        tbody.append(tr);
      });
      // Trailing empty row: typing in it adds a column.
      const ghostName = h('input', { class: 'ct-cell mono', placeholder: '+ new column', spellcheck: 'false', autocomplete: 'off' });
      ghostName.addEventListener('input', () => {
        const c = { id: rid(), name: ghostName.value, type: '', nullable: true, def: '' };
        st.cols.push(c);
        paintRows({ row: st.cols.length - 1, key: 'name', caret: ghostName.value.length });
        paintPk();
      });
      tbody.append(h('tr', { class: 'ct-row ghost' }, h('td', null, ghostName), h('td'), h('td'), h('td'), h('td')));
      if (focus) {
        const tr = tbody.children[focus.row];
        const input = tr && tr.querySelectorAll('.ct-cell')[{ name: 0, type: 1, nullable: 2, def: 3 }[focus.key] || 0];
        if (input) { input.focus(); if (focus.caret !== undefined && input.setSelectionRange) input.setSelectionRange(focus.caret, focus.caret); }
      }
    }

    function addCol(at) {
      const c = { id: rid(), name: '', type: '', nullable: true, def: '' };
      const i = at === undefined ? st.cols.length : at;
      st.cols.splice(i, 0, c);
      paintRows({ row: i, key: 'name' });
      paintPk();
    }
    function removeCol(i) {
      const [c] = st.cols.splice(i, 1);
      st.pk = st.pk.filter((x) => x !== c.id);
      paintRows();
      paintPk();
    }
    function move(i, d) {
      const [c] = st.cols.splice(i, 1);
      st.cols.splice(i + d, 0, c);
      paintRows({ row: i + d, key: 'name' });
    }

    function showErrors(msg) {
      errBox.innerHTML = '';
      errBox.classList.toggle('hidden', !msg);
      if (msg) errBox.append(icon('x'), h('pre', { class: 'err-text' }, msg));
    }

    async function preview() {
      showErrors('');
      try {
        const sql = await opts.previewSql(spec());
        modal({
          title: 'CREATE TABLE',
          wide: true,
          body: h('pre', { class: 'ddl-code boxed', html: window.SqlEditor.highlight(sql + ';') }),
          actions: [
            { label: 'Copy SQL', onClick: () => { window.api.copy(sql + ';\n'); toast('Copied', 'ok'); return false; } },
            { label: 'Open in editor', onClick: () => opts.openInEditor(sql + ';\n') },
            { label: 'Create table', kind: 'primary', onClick: () => { create(); } },
          ],
        });
      } catch (e) { showErrors(e.message); }
    }

    async function create() {
      if (st.busy) return;
      showErrors('');
      let sql;
      try { sql = await opts.previewSql(spec()); } catch (e) { showErrors(e.message); return; }
      if (!(await opts.confirmProd(sql))) return;
      st.busy = true;
      createBtn.disabled = true;
      createBtn.textContent = 'Creating…';
      try {
        const r = await opts.runCreate(spec());
        st.created = true;
        toast(`Created table ${r.table}`, 'ok');
        opts.onCreated(r.table);
      } catch (e) {
        showErrors(e.message);
      } finally {
        st.busy = false;
        createBtn.disabled = false;
        createBtn.textContent = 'Create table';
      }
    }

    st.pk = [st.cols[0].id];
    paintRows();
    paintPk();

    const tab = {
      kind: 'create', title: st.name, icon: 'table', el,
      tooltip: `New table in ${opts.owner}`,
      isDirty: () => !st.created && (st.cols.length > 1 || st.cols[0].type !== 'NUMBER GENERATED ALWAYS AS IDENTITY' || st.cols[0].name !== 'id' || st.pk.length !== 1),
      onShow: () => { if (!tab.shown) { tab.shown = true; nameInput.focus(); nameInput.select(); } },
      onKey: (e) => {
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') { e.preventDefault(); create(); return true; }
        return false;
      },
    };
    return tab;
  }

  window.createTableTab = createTableTab;
  window.ctEnsureLists = ensureLists;
})();
